let dialog: Office.Dialog | null = null;

export function getGraphToken(): Promise<string> {
  return new Promise((resolve, reject) => {
    // FIXED URI: Points straight to the auth page on your site
    const authUrl = "https://cordusbailey02.github.io/PayrollAddin/auth.html";

    Office.context.ui.displayDialogAsync(
      authUrl,
      { height: 60, width: 40, displayInIframe: false },
      (asyncResult) => {
        if (asyncResult.status === Office.AsyncResultStatus.Failed) {
          reject(new Error(`Failed to open dialog: ${asyncResult.error.message}`));
          return;
        }

        dialog = asyncResult.value;

        // Catch the token string when broadcasted from the auth-popup child window
        dialog.addEventHandler(
          Office.EventType.DialogMessageReceived,
          (arg: Office.DialogParentMessageReceivedEventArgs) => {
            try {
              const messageData = JSON.parse(arg.message);

              if (messageData.status === "success") {
                if (dialog) dialog.close();
                resolve(messageData.token);
              } else {
                if (dialog) dialog.close();
                reject(new Error(messageData.error || "Authentication aborted."));
              }
            } catch (err) {
              if (dialog) dialog.close();
              reject(err);
            }
          }
        );
      }
    );
  });
}
